export async function openPatternPicker(source,name){
  const img=new Image();img.src=source;await img.decode();
  const dialog=document.createElement('dialog');dialog.className='video-dialog video-pattern-dialog';dialog.innerHTML='<header><h2>框选产品花型</h2><button type="button" class="pattern-close" aria-label="关闭花型取样">×</button></header><p>拖动框选一块有代表性的产品印花，避开房间、人物、家具与道具。仅裁片会作为创意画面的图像参考。</p><canvas aria-label="拖动框选花型区域"></canvas><p class="pattern-message" role="status">请选择产品表面区域，不要框整张照片。</p><button type="button" class="video-dialog-primary pattern-confirm" disabled>确认花型裁片</button>';document.body.append(dialog);
  const canvas=dialog.querySelector('canvas'),ctx=canvas.getContext('2d'),scale=Math.min(1,1000/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);let start=null,rect=null;
  const draw=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);if(rect){const x=rect.x*canvas.width,y=rect.y*canvas.height,w=rect.width*canvas.width,h=rect.height*canvas.height;ctx.fillStyle='#173e2d77';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,rect.x*img.naturalWidth,rect.y*img.naturalHeight,rect.width*img.naturalWidth,rect.height*img.naturalHeight,x,y,w,h);ctx.strokeStyle='#d9f5c0';ctx.lineWidth=3;ctx.strokeRect(x,y,w,h);}};draw();
  const point=e=>{const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};};
  canvas.onpointerdown=e=>{e.preventDefault();start=point(e);canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!start)return;const p=point(e);rect={x:Math.min(start.x,p.x),y:Math.min(start.y,p.y),width:Math.abs(start.x-p.x),height:Math.abs(start.y-p.y),side:'A'};draw();const valid=rect.width>=.06&&rect.height>=.06&&rect.width*rect.height<=.65;dialog.querySelector('.pattern-confirm').disabled=!valid;dialog.querySelector('.pattern-message').textContent=valid?'将仅使用框内花型，场景与内容重新创作。':'区域过小或包含过多原图，请只选择产品表面。';};canvas.onpointerup=()=>start=null;canvas.onpointercancel=()=>start=null;
  return new Promise(resolve=>{let result=null;dialog.querySelector('.pattern-confirm').onclick=()=>{result={...rect};dialog.close();};dialog.querySelector('.pattern-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();resolve(result);},{once:true});dialog.showModal();});
}
